### Testing Pure Logic

```js
// src/utils/formatCurrency.js
export function formatCurrency(amount, currency = 'USD') {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency
  }).format(amount / 100); // amount in cents
}

// src/utils/formatCurrency.test.js
import { formatCurrency } from './formatCurrency';

describe('formatCurrency', () => {
  it('formats USD correctly', () => {
    expect(formatCurrency(1000)).toBe('$10.00');
  });

  it('formats zero as $0.00', () => {
    expect(formatCurrency(0)).toBe('$0.00');
  });

  it('formats other currencies', () => {
    expect(formatCurrency(1000, 'EUR')).toBe('€10.00');
  });

  it('throws for negative amounts', () => {
    expect(() => formatCurrency(-100)).toThrow();
  });
});
```

#### Testing React Components

```jsx
import { render, screen, fireEvent } from '@testing-library/react';
import { Counter } from './Counter';

describe('Counter', () => {
  it('renders initial count as 0', () => {
    render(<Counter />);
    expect(screen.getByText('Count: 0')).toBeInTheDocument();
  });

  it('increments when + button is clicked', () => {
    render(<Counter />);
    fireEvent.click(screen.getByRole('button', { name: '+' }));
    expect(screen.getByText('Count: 1')).toBeInTheDocument();
  });

  it('disables increment at max', () => {
    render(<Counter max={3} initialCount={3} />);
    expect(screen.getByRole('button', { name: '+' })).toBeDisabled();
  });
});
```

