### Testing Your API Routes for Real

```js
import request from 'supertest';
import { app } from '../app';
import { db } from '../db';

// Use a test database
beforeAll(() => db.connect(process.env.TEST_DATABASE_URL));
afterAll(() => db.disconnect());
beforeEach(() => db.users.deleteMany()); // Clean slate each test

describe('POST /api/users', () => {
  it('creates a user and returns 201', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ name: 'Alice', email: 'alice@example.com', password: 'SecurePass1!' })
      .expect(201);

    expect(res.body).toMatchObject({
      id: expect.any(String),
      name: 'Alice',
      email: 'alice@example.com',
    });
    expect(res.body.password).toBeUndefined(); // Never leak password
  });

  it('returns 400 for invalid email', async () => {
    const res = await request(app)
      .post('/api/users')
      .send({ name: 'Bob', email: 'not-an-email', password: 'SecurePass1!' })
      .expect(400);

    expect(res.body.error).toBeDefined();
  });

  it('returns 409 for duplicate email', async () => {
    await db.users.create({ name: 'Alice', email: 'alice@example.com' });

    await request(app)
      .post('/api/users')
      .send({ name: 'Alice 2', email: 'alice@example.com', password: 'SecurePass1!' })
      .expect(409);
  });
});
```

