### Testing Full User Flows in a Real Browser

```js
import { test, expect } from '@playwright/test';

test.describe('Authentication flow', () => {
  test('user can sign up and log in', async ({ page }) => {
    // Navigate to signup
    await page.goto('/signup');

    // Fill the form
    await page.fill('[name="email"]', 'alice@example.com');
    await page.fill('[name="password"]', 'SecurePass1!');
    await page.fill('[name="confirmPassword"]', 'SecurePass1!');

    // Submit
    await page.click('[type="submit"]');

    // Should redirect to dashboard
    await expect(page).toHaveURL('/dashboard');
    await expect(page.locator('h1')).toContainText('Welcome');
  });

  test('shows error on invalid credentials', async ({ page }) => {
    await page.goto('/login');
    await page.fill('[name="email"]', 'wrong@example.com');
    await page.fill('[name="password"]', 'wrongpassword');
    await page.click('[type="submit"]');

    await expect(page.locator('.error-message')).toBeVisible();
    await expect(page.locator('.error-message')).toContainText('Invalid credentials');
  });
});

// Visual regression test
test('landing page looks correct', async ({ page }) => {
  await page.goto('/');
  await expect(page).toHaveScreenshot('landing-page.png');
});
```

```bash
# Run tests in all browsers
npx playwright test

# Run with visual reporter
npx playwright test --reporter=html

# Record a new test by clicking through the app
npx playwright codegen http://localhost:5173
```

